{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Visible label that names the collection. It also provides the accessible name for the complete input.",
      "required": true
    },
    {
      "name": "value",
      "type": "T[]",
      "description": "Current ordered records. ListInput is controlled and never mutates this array or its records.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(next: T[], change: ListInputChange<T>) => void",
      "description": "Called with the next array after an add, update, or remove action. The change argument identifies the action and affected record. Moves go to the reorderable object instead.",
      "required": true
    },
    {
      "name": "getItemKey",
      "type": "(item: T) => React.Key",
      "description": "Returns a stable, unique key for each record. Stable identity preserves focus and announcements when records move.",
      "required": true
    },
    {
      "name": "createItem",
      "type": "() => T",
      "description": "Creates the initial record inserted by the built-in add action. Return a new record with its stable key already assigned.",
      "required": true
    },
    {
      "name": "columns",
      "type": "ListInputColumn<T>[]",
      "description": "Consistent simple fields shown for every record. Use each column width with proportional() or pixel() from @astryxdesign/core/Table to tune the width spread. ListInput owns the visible primary-tone column labels while renderer labels remain semantically available to assistive technology. At 640px or narrower, fields stack, every record shows its field labels, record groups use 32px vertical separation, and row actions align beside the first field. Renderers receive isLabelHidden, complete scoped validation status, statusVariant, and updateItem.",
      "required": true
    },
    {
      "name": "itemName",
      "type": "string",
      "description": "Singular noun used in built-in action labels and live announcements, such as \"guest\" in \"Add guest\"."
    },
    {
      "name": "description",
      "type": "string",
      "description": "Supporting text displayed between the collection label and its records."
    },
    {
      "name": "status",
      "type": "InputStatus",
      "description": "List-level validation status displayed for the complete collection. An error marks the collection invalid and associates its message with the input."
    },
    {
      "name": "getItemStatus",
      "type": "(item: T, index: number) => InputStatus | undefined",
      "description": "Returns validation status for a complete record, such as an invalid combination of otherwise valid fields."
    },
    {
      "name": "getFieldStatus",
      "type": "(item: T, columnKey: string, index: number) => InputStatus | undefined",
      "description": "Returns validation status for one field. The renderer receives the complete status plus statusVariant=\"tooltip\" and should forward both to its Astryx input so the native status affordance owns styling, description, keyboard access, and tooltip behavior without changing row height."
    },
    {
      "name": "reorderable",
      "type": "Reorderable",
      "description": "Makes the records reorderable: pass the object createReorderable makes, keyed by getItemKey. Each record ends with core List's reorder handle, after Remove, as UIKit's reorder control ends an editing row. The handle appears while the record is hovered or holds keyboard focus and stays visible on touch screens. On a touch screen, hold the handle for a moment, then drag: the record stays in its place, dimmed, while a copy of it follows the finger and an accent line marks where it would land; the other records stay still, the list autoscrolls near its edges, and on release the records rearrange. A flick on the handle scrolls and a pinch zooms the page. A mouse drags at once the same way, and the records take their places without motion. Activating the handle (a tap, a click, Space or Enter) turns on reorder mode for its record: the line marks the record's place, each Arrow Up or Arrow Down moves it a place, a hint shows the moves and Done as buttons, and Escape or Done ends the mode, keeping the moves. The object's isReorderable(key) says which records move: one it rejects has no handle. Each move goes to the object's onReorder({key, to}), to being the record's index in value after the move. In a disabled or loading list the handles stay focusable but move nothing. Without it, the records keep their order."
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the collection and all built-in actions. The disabled state is also passed to each column renderer.",
      "default": "false"
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Marks the collection busy and prevents changes while work is pending. The loading state is also passed to each column renderer.",
      "default": "false"
    },
    {
      "name": "maxItems",
      "type": "number",
      "description": "Maximum number of records that can be added. Once the value reaches this limit, the built-in add action is unavailable."
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hides the collection label while keeping it available to assistive technology.",
      "default": "false"
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Displays an optional indicator beside the collection label. Mutually exclusive with isRequired.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Displays a required indicator beside the collection label and exposes the requirement to assistive technology. Mutually exclusive with isOptional.",
      "default": "false"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
